package main

import (
	"fmt"
	"os"
	"strings"
)

// Four more of the oracle/ emitter family. As before, the HEADER text IS the product — every byte
// is output `task data-regen -- --check` compares against what is committed.

// ------------------------------------------------------------------------- pantheons

const oePantheonsHeader = `package data

// The pantheon soul data PoB's src/Data/Pantheons.lua (` + "`data.pantheons`" + `) holds, derived from the game's
// PantheonPanelLayout as PoB's Export/Scripts/pantheons.lua derives it (scripts/gamedatadump pantheons).
//
// CODE GENERATED BY scripts/gopob pantheons-emit FROM %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only pantheons`" + ` after a go-pob-data bump.
//
// The previous revision was a hand transcription of v2.18.1 with no emitter, which is how it
// came to carry 3.20's pantheon changes as drift: renamed capturable souls, two gods whose soul
// lists were REORDERED, a rewritten mod line ("Cannot be Frozen" -> "100%% chance to Avoid being
// Frozen") and four missing keys.

// PantheonSoul mirrors one entry of a god's ` + "`souls`" + ` table. PoB stores each mod as
// ` + "`{ line = ..., value = ... }`" + `; only ` + "`line`" + ` is ever read, so ` + "`value`" + ` is not carried over.
type PantheonSoul struct {
	Name string
	Mods []string
}

// Pantheon mirrors one god. Souls are in PoB's table order: index 0 is the base soul and the
// rest are the capturable upgrade souls.
//
// ⚠️ THE ORDER IS LOAD-BEARING, NOT COSMETIC. calculator/env.go:1340 labels every mod of the god
// with ` + "`Souls[0].Name`" + `, so a whole god reads as one "Pantheon:Soul of X" source regardless of
// which soul supplied the mod.
type Pantheon struct {
	Souls      []PantheonSoul
	IsMajorGod bool
}

// Pantheons is keyed exactly as PoB keys it, which is also the value stored in the build XML's
// pantheonMajorGod / pantheonMinorGod attributes.
//
// ⚠️ FOUR KEYS CARRY NO SOULS AT ALL — "Minor God 1", "2", "4" and "9" are ` + "`souls = {}`" + ` upstream.
// MEASURED against Data/Pantheons.lua:125-129, :130-134, :154-158 and :233-237, because the
// tempting reading is the opposite one and it was published here as fact: an earlier note in
// data/pob_data_drift_test.go called them "REAL entries, not placeholders — checked". They are
// placeholders. applySoulMod already returns early on a god with no souls, so carrying them
// changes nothing and closes the key-set finding honestly rather than by exclusion.
`

func oraclePantheonsEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: pantheons_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	// REFUSE rather than emit a plausible empty file. A zero-god table compiles, passes
	// `go build`, and turns every pantheon in the corpus into a silent no-op.
	if !oeTruthy(dump["gods"]) {
		//go-only: the dump now comes from scripts/gamedatadump, not the retired oracle/pantheons.lua
		return oeRefuse("the dump has no 'gods'. Re-run go run ./scripts/gamedatadump pantheons.")
	}
	gods := oeObject(dump["gods"])

	lines := []string{fmt.Sprintf(oePantheonsHeader, oeVersion(dump))}
	lines = append(lines, "var Pantheons = map[string]Pantheon{")

	soulsTotal, modsTotal, empty := 0, 0, 0
	for _, godName := range oeSortedKeys(gods) {
		god := oeObject(gods[godName])
		souls := oeArray(god["souls"])
		if len(souls) == 0 {
			empty++
		}
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(godName)))
		major := "false"
		if oeTruthy(god["isMajorGod"]) {
			major = "true"
		}
		lines = append(lines, fmt.Sprintf("\t\tIsMajorGod: %s,", major))
		if len(souls) == 0 {
			// An explicit empty literal rather than an omitted field: `Souls: nil` and "this god
			// has no souls" are the same thing to Go, and saying it out loud is what stops the
			// next reader treating the row as a dump failure.
			lines = append(lines, "\t\tSouls:      nil,", "\t},")
			continue
		}
		lines = append(lines, "\t\tSouls: []PantheonSoul{")
		for _, soulAny := range souls {
			soul := oeObject(soulAny)
			name, ok := soul["name"].(string)
			if !ok || name == "" {
				return oeRefuse(fmt.Sprintf("%s: a soul has no name; the dump is malformed", godName))
			}
			mods := oeArray(soul["mods"])
			soulsTotal++
			lines = append(lines, "\t\t\t{", fmt.Sprintf("\t\t\t\tName: %s,", oeGoStr(name)))
			if len(mods) > 0 {
				lines = append(lines, "\t\t\t\tMods: []string{")
				for _, lineAny := range mods {
					s, ok := lineAny.(string)
					if !ok {
						return oeRefuse(fmt.Sprintf("%s/%s: a mod line is not a string", godName, name))
					}
					lines = append(lines, fmt.Sprintf("\t\t\t\t\t%s,", oeGoStr(s)))
					modsTotal++
				}
				lines = append(lines, "\t\t\t\t},")
			}
			lines = append(lines, "\t\t\t},")
		}
		lines = append(lines, "\t\t},", "\t},")
	}
	lines = append(lines, "}", "")

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d gods (%d with no souls), %d souls, %d mod lines\n",
		argv[1], len(gods), empty, soulsTotal, modsTotal)
	return 0
}

// --------------------------------------------------------------------- cluster-jewels

const oeClusterJewelsHeader = `package data

// ClusterJewels mirrors PoB's src/Data/ClusterJewels.lua (` + "`data.clusterJewels`" + `), derived from the
// game's PassiveTreeExpansion* and PassiveJewelSlots tables as PoB's Export/Scripts/cluster.lua derives it
// (scripts/gamedatadump cluster-jewels). Field names keep PoB's spelling, including the upstream typo in "Indicies".
//
// CODE GENERATED BY scripts/gopob cluster-jewels-emit FROM %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only cluster-jewels`" + ` after a go-pob-data bump.
//
// The previous revision of this file was a hand transcription of PoB v2.18.1 with no
// emitter, which is why it still carried 3.20's cluster-jewel rebalance as drift:
// TestPoBDataTableDrift grades it against the pin and found 303 divergences.

type ClusterJewelSkill struct {
	Name        string
	Icon        string
	MasteryIcon string
	Tag         string
	Stats       []string
	Enchant     []string
}

type ClusterJewel struct {
	Size            string
	SizeIndex       int
	MinNodes        int
	MaxNodes        int
	SmallIndicies   []int
	NotableIndicies []int
	SocketIndicies  []int
	TotalIndicies   int
	Skills          map[string]ClusterJewelSkill
}

type ClusterJewelData struct {
	Jewels           map[string]ClusterJewel
	NotableSortOrder map[string]int
	Keystones        []string
	// OrbitOffsets is each cluster socket's proxy node id, then the cluster's sizeIndex, to the
	// orbit index its subgraph starts at.
	OrbitOffsets map[int]map[int]int
}

`

func oeStrList(name string, values []any, indent string) []string {
	if len(values) == 0 {
		return nil
	}
	out := []string{fmt.Sprintf("%s%s: []string{", indent, name)}
	for _, v := range values {
		out = append(out, fmt.Sprintf("%s\t%s,", indent, oeGoStr(oeStr(v))))
	}
	return append(out, indent+"},")
}

func oeIntList(name string, values []any, indent string) []string {
	if len(values) == 0 {
		return nil
	}
	parts := make([]string, len(values))
	for i, v := range values {
		parts[i] = oeIntStr(v)
	}
	return []string{fmt.Sprintf("%s%s: []int{%s},", indent, name, strings.Join(parts, ", "))}
}

func oracleClusterJewelsEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: cluster_jewels_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	// REFUSE rather than emit a plausible empty file. A zero-jewel table compiles, passes
	// `go build`, and turns every cluster jewel in the corpus into a no-op.
	for _, field := range []string{"jewels", "keystones", "notableSortOrder", "orbitOffsets"} {
		if !oeTruthy(dump[field]) {
			//go-only: the dump now comes from scripts/gamedatadump
			return oeRefuse(fmt.Sprintf("the dump has no %s. Re-run go run ./scripts/gamedatadump cluster-jewels.",
				pyRepr(field)))
		}
	}
	jewels := oeObject(dump["jewels"])
	notables := oeObject(dump["notableSortOrder"])
	keystones := oeArray(dump["keystones"])
	offsets := oeObject(dump["orbitOffsets"])

	lines := []string{fmt.Sprintf(oeClusterJewelsHeader, oeVersion(dump))}
	lines = append(lines, "var ClusterJewels = ClusterJewelData{", "\tJewels: map[string]ClusterJewel{")

	skillTotal := 0
	for _, jewelName := range oeSortedKeys(jewels) {
		jewel := oeObject(jewels[jewelName])
		lines = append(lines,
			fmt.Sprintf("\t\t%s: {", oeGoStr(jewelName)),
			fmt.Sprintf("\t\t\tSize:      %s,", oeGoStr(oeStr(jewel["size"]))),
			fmt.Sprintf("\t\t\tSizeIndex: %s,", oeIntStr(jewel["sizeIndex"])),
			fmt.Sprintf("\t\t\tMinNodes:  %s,", oeIntStr(jewel["minNodes"])),
			fmt.Sprintf("\t\t\tMaxNodes:  %s,", oeIntStr(jewel["maxNodes"])))
		lines = append(lines, oeIntList("SmallIndicies", oeArray(jewel["smallIndicies"]), "\t\t\t")...)
		lines = append(lines, oeIntList("NotableIndicies", oeArray(jewel["notableIndicies"]), "\t\t\t")...)
		lines = append(lines, oeIntList("SocketIndicies", oeArray(jewel["socketIndicies"]), "\t\t\t")...)
		lines = append(lines, fmt.Sprintf("\t\t\tTotalIndicies: %s,", oeIntStr(jewel["totalIndicies"])))
		lines = append(lines, "\t\t\tSkills: map[string]ClusterJewelSkill{")
		skills := oeObject(jewel["skills"])
		skillTotal += len(skills)
		for _, skillKey := range oeSortedKeys(skills) {
			skill := oeObject(skills[skillKey])
			lines = append(lines,
				fmt.Sprintf("\t\t\t\t%s: {", oeGoStr(skillKey)),
				fmt.Sprintf("\t\t\t\t\tName: %s,", oeGoStr(oeStrOr(skill["name"], ""))),
				fmt.Sprintf("\t\t\t\t\tIcon: %s,", oeGoStr(oeStrOr(skill["icon"], ""))))
			if oeTruthy(skill["masteryIcon"]) {
				lines = append(lines, fmt.Sprintf("\t\t\t\t\tMasteryIcon: %s,",
					oeGoStr(oeStr(skill["masteryIcon"]))))
			}
			lines = append(lines, fmt.Sprintf("\t\t\t\t\tTag: %s,", oeGoStr(oeStrOr(skill["tag"], ""))))
			lines = append(lines, oeStrList("Stats", oeArray(skill["stats"]), "\t\t\t\t\t")...)
			lines = append(lines, oeStrList("Enchant", oeArray(skill["enchant"]), "\t\t\t\t\t")...)
			lines = append(lines, "\t\t\t\t},")
		}
		lines = append(lines, "\t\t\t},", "\t\t},")
	}

	lines = append(lines, "\t},", "\tNotableSortOrder: map[string]int{")
	for _, notable := range oeSortedKeys(notables) {
		lines = append(lines, fmt.Sprintf("\t\t%s: %s,", oeGoStr(notable), oeIntStr(notables[notable])))
	}
	lines = append(lines, "\t},", "\tKeystones: []string{")
	for _, keystone := range keystones {
		lines = append(lines, fmt.Sprintf("\t\t%s,", oeGoStr(oeStr(keystone))))
	}
	lines = append(lines, "\t},", "\tOrbitOffsets: map[int]map[int]int{")
	for _, proxy := range oeSortedKeys(offsets) {
		starts := oeObject(offsets[proxy])
		parts := make([]string, 0, len(starts))
		for _, sizeIndex := range oeSortedKeys(starts) {
			parts = append(parts, fmt.Sprintf("%s: %s", sizeIndex, oeIntStr(starts[sizeIndex])))
		}
		lines = append(lines, fmt.Sprintf("\t\t%s: {%s},", proxy, strings.Join(parts, ", ")))
	}
	lines = append(lines, "\t},", "}", "")

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d jewels, %d skills, %d notables, %d keystones\n",
		argv[1], len(jewels), skillTotal, len(notables), len(keystones))
	return 0
}

// oeStrOr is python's `d.get(k, default)` where the value is expected to be a string: a MISSING
// key gives the default, and a present non-string is passed through str() as the original does.
func oeStrOr(v any, def string) string {
	if v == nil {
		return def
	}
	return oeStr(v)
}
